<script setup>import {computed} from 'vue';const props=defineProps({seats:{type:Array,default:()=>[]},selected:{type:Array,default:()=>[]}});const emit=defineEmits(['toggle']);const floors=computed(()=>[...new Set(props.seats.map(s=>s.floor))]);</script>
<template><div class="figma-seat-wrap"><div class="seat-legend"><span><i></i>Ghế trống</span><span><i class="picked"></i>Ghế đã đặt</span><span><i class="selected"></i>Ghế đang chọn</span></div><div class="bus-floor" v-for="floor in floors" :key="floor"><div class="floor-label">▣ {{floors.length>1?'Tầng '+floor:'Sơ đồ ghế'}}</div><div class="steering">◉ Tài xế</div><div class="seat-map"><button v-for="seat in seats.filter(s=>s.floor===floor)" :key="seat.id" :style="{gridColumn:seat.column}" class="seat" :class="selected.includes(seat.id)?'chosen':seat.status==='AVAILABLE'?'available':'booked'" :disabled="seat.status!=='AVAILABLE'" @click="emit('toggle',seat)">{{seat.number}}</button></div></div></div></template>
